static int contains(const unsigned char*b,size_t n,const char*s){size_t z=strlen(s),i;if(z>n)return 0;for(i=0;i+z<=n;i++)if(!memcmp(b+i,s,z))return 1;{const unsigned char raw[]={2,0,0,2,0,0,0,1,1,0x49,0,15,'d','o','c','u','m','e','n','t','-','f','o','r','m','a','t',0,24,'a','p','p','l','i','c','a','t','i','o','n','/','o','c','t','e','t','-','s','t','r','e','a','m',3};unsigned char bad[sizeof raw];memcpy(bad,raw,sizeof raw);assert(ipp_raw_format_supported(raw,sizeof raw)==1);memcpy(bad+28,"application/pdf",15);assert(ipp_raw_format_supported(bad,sizeof bad)==0);}return 0;}
static int contains_bytes(const unsigned char*b,size_t n,const unsigned char*v,size_t z){size_t i;if(z>n)return 0;for(i=0;i+z<=n;i++)if(!memcmp(b+i,v,z))return 1;return 0;}
int main(void){const unsigned char q[]={2,0,0,0x0b,0,0,0,7};const unsigned char print_op[]={0,0,0,2};const unsigned char validate_op[]={0,0,0,4};const unsigned char attrs_op[]={0,0,0,0x0b};struct ipp_request r;unsigned char z[2048];size_t n;assert(ipp_parse_header(q,sizeof q,&r)==0);assert(r.major==2&&r.minor==0&&r.operation==IPP_OP_GET_PRINTER_ATTRIBUTES&&r.request_id==7);assert(!strcmp(ipp_operation_name(IPP_OP_PRINT_JOB),"Print-Job"));assert(ipp_parse_header(q,7,&r)==-1);assert(ipp_build_status(z,sizeof z,&r,0)==9);assert(z[0]==2&&z[1]==0&&z[2]==0&&z[3]==0&&z[7]==7&&z[8]==3);n=ipp_build_printer_attributes(z,sizeof z,&r,"ipp://minibox.local/ipp/print");assert(n>9);assert(z[0]==2&&z[1]==0&&z[7]==7);assert(z[8]==0x04);assert(z[n-1]==0x03);assert(contains(z,n,"printer-name"));assert(contains(z,n,"HP LaserJet M1522n @ MiniBox"));assert(contains(z,n,"printer-uri-supported"));assert(contains(z,n,"ipp://minibox.local/ipp/print"));assert(contains(z,n,"operations-supported"));assert(contains_bytes(z,n,print_op,sizeof print_op));assert(contains_bytes(z,n,validate_op,sizeof validate_op));assert(contains_bytes(z,n,attrs_op,sizeof attrs_op));assert(contains(z,n,"document-format-supported"));return 0;}
